use gpui_dataset_transformation::{ftle,lic,particle_frames,streak_frames,streamlines,ParticleOptions,StreakOptions};
use gpui_mesh::{Association,DataSet,Field,TimeSeries};
use gpui_profiler::AllocProbe;
use std::{hint::black_box,time::Instant};

enum Output { Single(DataSet), Frames(Vec<DataSet>) }

fn check(output:&Output,n:usize,case:&str) {
    match output {
        Output::Single(output)=>{
            output.validate().unwrap();
            if case=="streamlines" { assert_eq!(output.point_count(),416); assert_eq!(output.cell_count(),384); assert!(output.positions.iter().all(|p|p[0]>0.1 && p[0]<0.9)); }
            else {
                let field=output.field(Association::Point,case).unwrap();
                let values=field.as_scalar().unwrap();
                if case=="lic" { assert!(values.iter().all(|v|(0.0..1.0).contains(v))); }
                else {
                    assert!(values.iter().all(|v|v.is_nan() || v.abs()<1e-8));
                    let valid=(0..values.len()).filter(|&i|field.is_valid(i)).count();
                    assert_eq!(valid,if cfg!(feature="retained") {(n-2).pow(3)} else {n.pow(3)});
                }
            }
        },
        Output::Frames(frames)=>{
            assert_eq!(frames.len(),8);
            for (frame,output) in frames.iter().enumerate() {
                output.validate().unwrap();
                let trail=(frame+1).min(4);
                assert_eq!(output.point_count(),16*trail);
                for seed in 0..16 { assert!((output.positions[seed*trail+trail-1][0]-(0.5+0.001*frame as f64)).abs()<1e-12); }
            }
        },
    }
}

fn main() {
    let reverse=std::env::args().nth(1).as_deref()==Some("reverse");
    for n in [4usize,6,8] {
        let dataset=DataSet::structured_grid("trace",[n;3],[0.0;3],[0.5;3]).unwrap();
        let count=dataset.point_count();
        let dataset=dataset.with_field(Field::vector("v",vec![[0.1,0.0,0.0];count]));
        let series=TimeSeries::new(vec![dataset.clone(),dataset.clone()],vec![0.0,1.0]).unwrap();
        let seeds=(0..16).map(|i|[0.5,0.5+(i%4) as f64*0.05,0.5+(i/4) as f64*0.05]).collect::<Vec<_>>();
        let order=if reverse {["ftle","lic","particles","streamlines"]} else {["streamlines","particles","lic","ftle"]};
        for case in order {
            let operation=||match case {
                "streamlines"=>Output::Single(streamlines(&dataset,"v",&seeds,0.025,12).unwrap()),
                "particles"=>Output::Frames(particle_frames(&series,"v",&seeds,ParticleOptions{dt:0.01,frames:8,trail:4}).unwrap()),
                "lic"=>Output::Single(lic(&dataset,"v",2,0.1,7).unwrap()),
                _=>Output::Single(ftle(&series,"v",0.0,0.02,0.01,2).unwrap()),
            };
            let warm=black_box(operation());check(&warm,n,case);drop(warm);
            let mut times=Vec::with_capacity(5);let mut calls=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
            for _ in 0..5 {
                let mut probe=AllocProbe::new();let start=Instant::now();let output=black_box(operation());let elapsed=start.elapsed().as_nanos();let sample=probe.sample("tracing");
                times.push(elapsed);calls.push(sample.count);bytes.push(sample.bytes);check(&output,n,case);drop(output);
            }
            println!(r#"{{"kind":"timing","n":{n},"case":"{case}","times_ns":{times:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
        }
    }
    let dataset=DataSet::structured_grid("time",[2;3],[0.0;3],[10.0;3]).unwrap();
    let series=TimeSeries::new(vec![dataset.clone().with_field(Field::vector("v",vec![[0.0;3];8])),dataset.with_field(Field::vector("v",vec![[1.0,0.0,0.0];8]))],vec![0.0,1.0]).unwrap();
    let frames=particle_frames(&series,"v",&[[1.0;3]],ParticleOptions{dt:0.5,frames:2,trail:8}).unwrap();
    let pathline_x=frames[1].positions.last().unwrap()[0];
    let streaks=streak_frames(&series,"v",&[[1.0;3]],StreakOptions{dt:0.5,frames:2,release_every:1}).unwrap();
    let newest_streak_x=streaks[1].positions.last().unwrap()[0];
    assert!((pathline_x-if cfg!(feature="retained") {1.125} else {1.375}).abs()<1e-12);
    assert!((newest_streak_x-if cfg!(feature="retained") {1.0} else {1.125}).abs()<1e-12);
    println!(r#"{{"kind":"semantic_repro","pathline_x":{pathline_x},"newest_streak_x":{newest_streak_x}}}"#);
}
